 use dm_analysis::{check_policy::{DiagnosticSeverity as S,cli_printed}};let project=std::env::args().nth(1).ok_or("expected project")?;let family=std::env::args().nth(2).ok_or("expected call_arguments|filter_call family")?;if !matches!(family.as_str(),"call_arguments"|"filter_call"|"catch_parameter_count"|"static_reference"){return Err("expected call_arguments|filter_call family".into())}let project=Path::new(&project);if !project.is_absolute(){return Err("project must be caller absolute".into())}
 let files=acquired_files::AcquiredFiles::default();let seed=reference_hierarchy::seed();let db=Arc::new(dmbc::query_db::QueryDb::default());let host:Arc<dyn dm_tree::frontend::SettingExpressionQueries>=db.clone();let executor=dm_exec::BuildExecutor::new(1)?;let front=dm_tree::frontend::build_for_checker_diagnostics_with_state_checked(project,&files,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,&executor,None,&host).map_err(|e|format!("native call-argument diagnostic frontend: {e:?}"))?.with_body_queries(db.clone())?;let view=front.source_view()?;let archive=view.archive();let tree=archive.tree();let profile=tree.checker_builtin_profile().ok_or("actual checker profile absent")?;
 let selected=dm_analysis::check_configuration::select(project,None);let bytes=match std::fs::read(&selected.path){Ok(bytes)=>Some(bytes),Err(actual)if actual.kind()==io::ErrorKind::NotFound=>None,Err(actual)=>return Err(actual.into())};let loaded=dm_analysis::check_configuration::load(&selected,dm_analysis::check_configuration::Capture{path:&selected.path,read:match &bytes{Some(bytes)=>dm_analysis::check_configuration::CapturedRead::Bytes(bytes),None=>dm_analysis::check_configuration::CapturedRead::AutodetectAbsent}})?;let expected=if family=="catch_parameter_count"{S::Warning}else{S::Error};let Some(level)=loaded.policy.register(None,expected).filter(|level|cli_printed(*level))else{return Ok(())};let mut output=std::io::stdout().lock();let mut work=OracleWork{bytes:0};
 for(ordinal,_)in dm_analysis::checker_order::archived_bodies(archive)?{let body=archive.parse_checked(ordinal).map_err(|e|format!("actual body: {e:?}"))?;let render=|findings:&dm_analysis::checks_proc_visibility::Findings<'_>|{for finding in findings.iter(){let row=finding.diagnostic();let point=finding.borrowed_reported_point()?;let(path,line,column)=point.coordinates();let file=project.parent().ok_or("project parent absent")?.join(path);let notes=row.notes.iter().map(|note|note.legacy_text()).collect::<Vec<_>>();serde_json::to_writer(&mut output,&serde_json::json!({"family":row.family,"severity":match level{S::Error=>"error",S::Warning=>"warning",S::Info=>"info",S::Hint=>"hint"},"file":file,"line":line,"expanded_column":column,"message":row.message,"notes":notes})).map_err(|e|dm_analysis::policy_body_demand::PolicyFailure::Operational(io::Error::from(e)))?;output.write_all(b"\n").map_err(dm_analysis::policy_body_demand::PolicyFailure::Operational)?;}Ok(())};if family=="static_reference"{dm_analysis::checks_call_arguments::with_static_references_archived_body(archive,&body,tree,profile,&mut work,&||Ok(()),render)}else if family=="catch_parameter_count"{dm_analysis::checks_call_arguments::with_catch_parameters_archived_body(archive,&body,tree,profile,&mut work,&||Ok(()),render)}else if family=="filter_call"{dm_analysis::checks_call_arguments::with_filter_archived_body(archive,&body,tree,profile,&mut work,&||Ok(()),render)}else{dm_analysis::checks_call_arguments::with_archived_body(archive,&body,tree,profile,&mut work,&||Ok(()),render)}.map_err(failure)?;}Ok(())
